// 输入: OpcUa-Event 的 msg.payload（含 eventType 与自定义字段）
const p = msg.payload || {};
const et = String(p.eventType || p.EventType || '');
const now = Date.now();
// 陈旧事件过滤：断网恢复后的 overflow 旧事件直接丢弃（红线3-陈旧事件处理）
let src = p.sourceTimestamp || p.SourceTimestamp || p.time || p.Time;
let ts = src ? new Date(src).getTime() : now;
if (!isFinite(ts)) ts = now;
const age = now - ts;
if (age > 60000) {
    node.warn('陈旧事件丢弃(age=' + Math.round(age/1000) + 's): ' + (p.message || et));
    return null;
}
const common = {
    workOrderId: p.workOrderId ?? p.WorkOrderId ?? '',
    serialNumber: p.serialNumber ?? p.SerialNumber ?? '',
    imageId: p.imageId ?? p.ImageId ?? '',
    confidence: p.confidence ?? p.Confidence ?? null
};
if (/NgDetected/i.test(et)) {
    // NG 开单唯一触发源：NgDetectedEvent（红线1-完结事件触发源同理由 WorkOrderCompletedEvent 承担）
    const m = Object.assign({}, common, {
        defectType: p.defectType ?? p.DefectType ?? '',
        occurredAt: new Date(ts).toISOString()  // ISO8601 UTC(带Z)，规避时区偏移
    });
    return [m, null];
}
if (/WorkOrderCompleted/i.test(et)) {
    // 报工唯一发令枪：WorkOrderCompletedEvent，不由 Node-RED 自行推断
    const m = {
        workOrderId: p.workOrderId ?? p.WorkOrderId ?? '',
        inspectCount: p.inspectCount ?? p.InspectCount ?? 0,
        okCount: p.okCount ?? p.OkCount ?? 0,
        ngCount: p.ngCount ?? p.NgCount ?? 0,
        ngRate: p.ngRate ?? p.NgRate ?? -1,
        occurredAt: new Date(ts).toISOString()
    };
    return [null, m];
}
// InspectionFinished(OK)等其他事件仅记录不动作，避免 NG 双发
return null;

// 告警疲劳防护：10s 抑制窗内合并计数，超窗才亮一次灯并携带被合并数
const last = context.get('lastAlarmTs') || 0;
const now = Date.now();
if (now - last < 10000) {
    context.set('suppressed', (context.get('suppressed') || 0) + 1);
    node.warn('告警抑制: 10s窗口内合并NG');
    return null;
}
context.set('lastAlarmTs', now);
msg.suppressedCount = context.get('suppressed') || 0;
context.set('suppressed', 0);
node.warn('[NG报警] ' + msg.serialNumber + ' ' + msg.defectType + (msg.suppressedCount ? ' (已合并' + msg.suppressedCount + '条)' : ''));
return msg;

// 防重：serialNumber+occurredAt 指纹（红线2-防重机制；MES侧还有第二道防线）
const seen = context.get('ngSeen') || {};
const fp = msg.serialNumber + '|' + msg.occurredAt;
if (seen[fp]) { node.warn('重复NG丢弃: ' + fp); return null; }
seen[fp] = 1;
const keys = Object.keys(seen);
if (keys.length > 500) delete seen[keys[0]];
context.set('ngSeen', seen);
return msg;

// 边缘缓冲：内存队列 PENDING（M2 起点；SQLite 持久化为 M3 可选升级 Phase0 §6-5）
// 报文结构与 M1契约 §3.1 绝对一致，字段名大小写不增不减
const q = context.get('buf') || [];
q.push({ id: msg.serialNumber + '|' + msg.occurredAt, type: 'ng',
    url: 'http://127.0.0.1:1880/mes/ng-order',
    body: { workOrderId: msg.workOrderId, serialNumber: msg.serialNumber, defectType: msg.defectType,
            confidence: msg.confidence, imageId: msg.imageId, occurredAt: msg.occurredAt },
    attempts: 0, nextAt: 0, status: 'PENDING' });
context.set('buf', q);
node.status({ text: '队列=' + q.length });
return null;

// 防重：报工按 workOrderId 指纹（红线2-防重：绝不重复报工）
const seen = context.get('doneSeen') || {};
if (seen[msg.workOrderId]) { node.warn('重复报工丢弃: ' + msg.workOrderId); return null; }
seen[msg.workOrderId] = 1;
context.set('doneSeen', seen);
return msg;

const q = context.get('buf') || [];
q.push({ id: msg.workOrderId, type: 'complete',
    url: 'http://127.0.0.1:1880/mes/complete',
    body: { workOrderId: msg.workOrderId, inspectCount: msg.inspectCount, okCount: msg.okCount,
            ngCount: msg.ngCount, ngRate: msg.ngRate },
    attempts: 0, nextAt: 0, status: 'PENDING' });
context.set('buf', q);
node.status({ text: '队列=' + q.length });
return null;

// 状态机: PENDING -> SENDING -> SUCCESS(出队) / PENDING(退避) / FAILED(死信)。单向闭环，无卡死状态
const q = context.get('buf') || [];
const now = Date.now();
const item = q.find(it => it.status === 'PENDING' && it.nextAt <= now);
if (!item) { node.status({ text: '队列=' + q.length }); return null; }
item.status = 'SENDING';  // 单飞行：上一条未返回前不会再发下一条
msg.url = item.url;
msg.headers = { 'content-type': 'application/json' };
msg.payload = item.body;
msg._qc = { id: item.id, type: item.type, attempts: item.attempts };
node.status({ text: '发送 ' + item.type + ' ' + item.id });
return msg;

const q = context.get('buf') || [];
const item = msg._qc || {};
const i = q.findIndex(it => it.id === item.id);
const st = msg.statusCode || 0;
if (st >= 200 && st < 300) {
    if (i >= 0) q.splice(i, 1);
    context.set('buf', q);
    if (item.type === 'ng') {
        const orderNo = (msg.payload && msg.payload.mesOrderNo) || '';
        node.warn('[回执] MES工单号=' + orderNo + ' → 写回 LastMesOrderNo（不覆盖派工单号）');
        // 回执写回 UA：独立变量 LastMesOrderNo（红线4-状态回写闭环）
        return { topic: 'ns=2;s=QCStation.LastMesOrderNo', action: 'write', payload: orderNo };
    }
    node.warn('[报工成功] ' + item.id + ' receipt=' + (msg.payload && msg.payload.receiptNo));
    return null;
}
// 失败路径：3次重试 1s/2s/4s 指数退避（红线2-超时与退避）；超限转 FAILED 死信，不阻塞队列
item.attempts = (item.attempts || 0) + 1;
if (item.attempts >= 3) {
    if (i >= 0) q.splice(i, 1);
    context.set('buf', q);
    const dead = context.get('dead') || [];
    dead.push(Object.assign({}, item, { lastStatus: st }));
    context.set('dead', dead);
    node.error('[死信FAILED] ' + item.type + ' ' + item.id + ' 重试3次仍失败(lastStatus=' + st + ')，需人工处置', item.body);
    return null;
}
item.status = 'PENDING';
item.nextAt = Date.now() + [1000, 2000, 4000][item.attempts - 1];
if (i >= 0) q[i] = item;
context.set('buf', q);
node.warn('[重试] ' + item.type + ' ' + item.id + ' 失败(status=' + st + ')，' + [1000,2000,4000][item.attempts-1] + 'ms 后第' + (item.attempts+1) + '次尝试');
return null;

// 心跳成功即复位假死计数（红线3-断网重连探测）
if (msg._hb) { context.set('hbFails', 0); return null; }
if (msg._qcType === 'ua_write') { return null; }
const p = msg.payload;
const outs = Array.isArray(p) ? p : ((p && p.OutputArguments) || []);
const accepted = outs[0];
if (accepted === false) {
    // Method 拒绝：打印原因并阻断（绝不带病继续报工）
    node.error('[UA拒绝] ' + (outs[1] || 'unknown') + ' —— 已阻断后续动作');
} else if (accepted === true) {
    node.warn('[UA成功] ' + (outs[1] || ''));
}
return null;

// 连续3次异常判定假死/断开（红线3-断网重连探测：不依赖底层库自动重建的假设）
const n = (context.get('hbFails') || 0) + 1;
context.set('hbFails', n);
if (n >= 3) {
    node.error('[连接告警] 连续' + n + '次UA异常，疑似断网/假死。短时断网应由ActivateSession恢复原会话；长时断网需主动重建订阅（见Phase0断网恢复机制）', msg.error ? msg.error.message : '');
}
return null;

msg.action = 'callmethod';
msg.topic = 'ns=2;s=QCStation.StartInspection';
msg.payload = { inputArguments: [
    { dataType: 'String', value: 'WO-20261109-001' },
    { dataType: 'UInt32', value: 5 }
] };
return msg;

msg.action = 'callmethod';
msg.topic = 'ns=2;s=QCStation.CompleteWorkOrder';
msg.payload = { inputArguments: [ { dataType: 'String', value: 'WO-20261109-001' } ] };
return msg;

context.set('mesMode', msg.payload);
node.warn('MES故障注入模式 = ' + msg.payload + '（ok / 5xx / timeout）');
return null;

const mode = context.get('mesMode') || 'ok';
const body = msg.payload || {};
const orders = context.get('orders') || {};
const fp = body.serialNumber;
// MES侧第二道防重：同SN重复开单直接返回原单号（绝不生成两张NG工单）
if (orders[fp]) {
    msg.statusCode = 200;
    msg.payload = { accepted: true, mesOrderNo: orders[fp], duplicated: true };
    return [msg, null];
}
const make = () => {
    const seq = (context.get('mesSeq') || 0) + 1;
    context.set('mesSeq', seq);
    const d = new Date();
    const orderNo = 'MES-' + d.toISOString().slice(0,10).replace(/-/g,'') + '-' + String(seq).padStart(4,'0');
    orders[fp] = orderNo;
    context.set('orders', orders);
    return orderNo;
};
if (mode === '5xx') {
    node.warn('[MES注入5xx] 拒绝NG单 ' + fp);
    msg.statusCode = 500;
    msg.payload = { accepted: false, error: 'simulated internal error' };
    return [msg, null];
}
if (mode === 'timeout') {
    node.warn('[MES注入timeout] 延迟10s响应（客户端3s超时将触发退避重试）');
    setTimeout(() => {
        msg.statusCode = 200;
        msg.payload = { accepted: true, mesOrderNo: make() };
        node.send([msg, null]);
    }, 10000);
    return null;
}
msg.statusCode = 200;
msg.payload = { accepted: true, mesOrderNo: make() };
return [msg, null];

const mode = context.get('mesMode') || 'ok';
const body = msg.payload || {};
const receipts = context.get('receipts') || {};
if (receipts[body.workOrderId]) {
    msg.statusCode = 200;
    msg.payload = { accepted: true, receiptNo: receipts[body.workOrderId], duplicated: true };
    return [msg, null];
}
const make = () => {
    const seq = (context.get('rcSeq') || 0) + 1;
    context.set('rcSeq', seq);
    const r = 'RC-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + String(seq).padStart(4,'0');
    receipts[body.workOrderId] = r;
    context.set('receipts', receipts);
    return r;
};
if (mode === '5xx') {
    msg.statusCode = 500;
    msg.payload = { accepted: false, error: 'simulated internal error' };
    return [msg, null];
}
if (mode === 'timeout') {
    setTimeout(() => {
        msg.statusCode = 200;
        msg.payload = { accepted: true, receiptNo: make() };
        node.send([msg, null]);
    }, 10000);
    return null;
}
msg.statusCode = 200;
msg.payload = { accepted: true, receiptNo: make() };
return [msg, null];
